using System;
using System.Linq;
using Microsoft.EntityFrameworkCore;
using SampleDotNet6App.Data;
using SampleDotNet6App.Models;
using Xunit;

namespace SampleDotNet6App.Data.Tests;

public class ApplicationDbContextTests
{
    [Fact]
    public void Constructor_WithValidOptions_CreatesContext()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_Constructor")
            .Options;

        // Act
        var context = new ApplicationDbContext(options);

        // Assert
        Assert.NotNull(context);
    }

    [Fact]
    public void Products_ReturnsDbSet()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_Products")
            .Options;
        var context = new ApplicationDbContext(options);

        // Act
        var productsSet = context.Products;

        // Assert
        Assert.NotNull(productsSet);
    }

    [Fact]
    public void Users_ReturnsDbSet()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_Users")
            .Options;
        var context = new ApplicationDbContext(options);

        // Act
        var usersSet = context.Users;

        // Assert
        Assert.NotNull(usersSet);
    }

    [Fact]
    public void OnModelCreating_ConfiguresProductEntity()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_ProductConfig")
            .Options;
        var context = new ApplicationDbContext(options);

        // Act
        var product = new Product { Id = 1, Name = "Test Product", Price = 99.99m };
        context.Products.Add(product);
        context.SaveChanges();

        // Assert
        var savedProduct = context.Products.Find(1);
        Assert.NotNull(savedProduct);
        Assert.Equal("Test Product", savedProduct.Name);
    }

    [Fact]
    public void OnModelCreating_ConfiguresUserEntity()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_UserConfig")
            .Options;
        var context = new ApplicationDbContext(options);

        // Act
        var user = new User { Id = 1, Username = "testuser", Email = "test@test.com", PasswordHash = "hash" };
        context.Users.Add(user);
        context.SaveChanges();

        // Assert
        var savedUser = context.Users.Find(1);
        Assert.NotNull(savedUser);
        Assert.Equal("testuser", savedUser.Username);
    }

    [Fact]
    public void Products_CanAddAndRetrieve()
    {
