            Assert.NotNull(user);
            Assert.Equal("user1", user.Username);
        }
    }

    [Fact]
    public void Products_CanUpdateEntity()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_UpdateProduct")
            .Options;

        using (var context = new ApplicationDbContext(options))
        {
            context.Products.Add(new Product { Id = 1, Name = "Original", Price = 10.00m });
            context.SaveChanges();
        }

        // Act
        using (var context = new ApplicationDbContext(options))
        {
            var product = context.Products.Find(1);
            product!.Name = "Updated";
            context.SaveChanges();
        }

        // Assert
        using (var context = new ApplicationDbContext(options))
        {
            var product = context.Products.Find(1);
            Assert.Equal("Updated", product!.Name);
        }
    }

    [Fact]
    public void Products_CanDeleteEntity()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_DeleteProduct")
            .Options;

        using (var context = new ApplicationDbContext(options))
        {
            context.Products.Add(new Product { Id = 1, Name = "ToDelete", Price = 10.00m });
            context.SaveChanges();
        }

        // Act
        using (var context = new ApplicationDbContext(options))
        {
